// DevicesStockSchema.js — FRONTEND schema: labels, formulas, remarks, click-throughs. Generated by gen-report.js from report.map (same folder).
// The numbers come from the backend twin app/api/mda4/reports/devices/stock/list/DevicesStockSchema.js (same measure keys).
import { getApiRoutes } from '../../../AppRoutes/apiRoutesHandler';
import DevicesStockActions from './logicControl/actionsRegistry';
const apiRoutes = getApiRoutes();

export const DevicesStockSchema = {
  entity: 'simukopa_devices_stock',
  label: 'Devices by Model',
  description: '',
  apiBase: apiRoutes.devicesstock?.base,
  moduleRole: 'view_reports',
  currency: 'KES',
  actionRegistry: DevicesStockActions,

  groupBy: 'model_name',
  groupLabel: 'Model',
  sortBy: 'phones desc',

  fields: [
    { key: 'phones', label: 'Devices', from: 'phones' },
    { key: 'in_stock', label: 'In Stock', from: 'phones' },
    { key: 'allocated', label: 'Allocated', from: 'phones' },
    { key: 'locked', label: 'Locked', from: 'phones' },
    { key: 'stock_value', label: 'Stock Value', from: 'phones.purchase_price', type: 'money' },
    { key: 'share', label: 'Share of Stock', calc: 'share(stock_value)' },
  ],

  remarks: [
    { if: 'in_stock == 0 && allocated > 0', tone: 'watch', title: 'Out of stock', say: '{label} has no stock left, with {allocated} devices allocated.' },
    { if: 'locked > 0', tone: 'watch', title: 'Locked devices', say: '{locked} {label} devices are locked.' },
    { if: 'true', tone: 'neutral', title: 'Stock', say: '{in_stock} in stock worth {stock_value}, {allocated} allocated.' },
  ],

  headline: '{label} has the most devices: {phones} in total, {in_stock} in stock and {allocated} allocated.',
};
